// TH15 v1.00b / st06bs.ecl.txt:738-833 BossCard1 "「掌の純光」".
// Dependencies: BossCard1_at 835-871, BossCard1_at2 873-907.
// Entry state (Boss 8-34, Boss1 53): boss at (0,128), hitbox 50x50 -> r25,
// hurtbox 56x56 -> r28, HP threshold 4000; shell is invulnerable (no player DPS).
// Card frame 0 = source timerReset; source t=0 at card frame 120.
const TIME_LIMIT: int = 3424;    // 120 opening + source 3300 + 4 startup
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 3300;
const TH15_BALL2: int = 432;     // source type 5, radius 4 (bullet-types.md)

// Source BossCard1_at 853-863 / BossCard1_at2 890-900 EX chain on the bullet:
// WAIT 30 -> VELTIME to 4.0 over 30 -> WAIT 15 -> VELTIME to 0.7 (at) / 0.6 (at2).
// ANIM birth retreat is folded into sh_dist: etDist 24 - 4*0.5 = 22.
xformdef AT_BULLET {
    wait(30);
    set_accel(0.1166666667fx);   // (4.0-0.5)/30
    wait(30);
    set_accel(0fx);
    wait(15);
    set_accel(-0.11fx);          // (0.7-4.0)/30
    wait(30);
    set_accel(0fx);
}
xformdef AT2_BULLET {
    wait(30);
    set_accel(0.1166666667fx);
    wait(30);
    set_accel(0fx);
    wait(15);
    set_accel(-0.1133333333fx);  // (0.6-4.0)/30
    wait(30);
    set_accel(0fx);
}

// Emitter 1 is the copied config whose EX slot 4 is LASER (859/896). Its parent
// bullet flies 60 frames with the same acceleration, then LASER deletes it (d=1).
xformdef PROXY_BULLET {
    wait(30);
    set_accel(0.1166666667fx);
    wait(30);
    set_accel(0fx);
    set_life(1);
}

// Laser direction = source line (LASER b=8 sprite, c=6/2 colour, d=1 delete parent).
// Source line: initial length 16, target/limit 128 (etExSet2 m=16,n=128); target
// lz_speed grows the judged rod from near 0. Width: source w=14 -> half
// h=w/4=3.5 -> target full width 7 (lasers.md). The source 0->4.5/0->3.6 ACCEL
// ramp of the laser is approximated by the final constant speed (allowed laser
// motion approximation; laser_approx=true). Source width/line geometry only.
async sub laser_slice(base: angle, n: int, half: int, color: int, spd: fx,
                       from: int, cnt: int) {
    wait(60);                    // parent bullet reaches EX slot 4 at age 60
    for i in from..from+cnt {
        var a: angle = base + (((i*65536)/n + half) as angle);
        // Bullet offset at conversion: 22 birth + 30*0.5 + 30*(0.5+4.0)/2 = 104.5.
        var x: fx = $self_x + 104.5fx*cos(a);
        var y: fx = $self_y + 104.5fx*sin(a);
        var h: int = laser(color, x, y, a, 0fx, 7fx, 0, 9999, 0);
        // Line judgement (flags 0x2 clear): [0.1L, 0.9L] of the 128 display length.
        lz_speed(h, spd, 102.4fx);
        lz_start(h, 12.8fx);
    }
}
// Same-frame volley split over parallel tasks so one task stays inside the
// per-frame instruction budget; all slices are spawned on the wave frame and
// first run together on the following frame.
sub spawn_lasers(base: angle, n: int, half: int, color: int, spd: fx) {
    var parts: int = 8;
    var per: int = (n + parts - 1) / parts;
    var k: int = 0;
    while k < parts {
        var lo: int = k*per;
        var cnt: int = per;
        if lo + cnt > n { cnt = n - lo; }
        if cnt > 0 { spawn laser_slice(base, n, half, color, spd, lo, cnt); }
        k = k + 1;
    }
}

// st06bs.ecl.txt:835-871. mode3 fixed ring, type5 colour6; count by rank
// (!E 48 / !N 96 / !H 108 / !LO 112); M=1 so only s0=0.5 is used.
// Each emitter fires from its own spawned task so one task does not burn the
// per-frame instruction budget with both 112-bullet volleys.
async sub fire_at_normal(a: angle, n: int) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, a, 0deg);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, 22fx);
    sh_xform(0, AT_BULLET);
    sh_fire(0);
}
// emitter 1: etCopy(1,0) 858, etAim(1,5) 867 -> half-step ring.
async sub fire_at_proxy(a: angle, n: int) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, a + ((32768/n) as angle), 0deg);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, 22fx);
    sh_xform(0, PROXY_BULLET);
    sh_fire(0);
}
sub at() {
    var rank: int = global(GVAR_RANK);
    var n: int = 48;
    if rank == 1 { n = 96; }
    if rank == 2 { n = 108; }
    if rank == 3 { n = 112; }
    var a: angle = (rand(65536) - 32768) as angle;  // %RANDRAD 864
    spawn fire_at_normal(a, n);
    spawn fire_at_proxy(a, n);
    spawn_lasers(a, n, 32768/n, 6, 4.5fx);
}

// st06bs.ecl.txt:873-907. type5 colour2; count !E 15 / others 33; laser colour 2;
// ACCEL r=0.04 over 90 -> final 3.6.
async sub fire_at2_normal(d: angle, n: int) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, d, 0deg);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, 22fx);
    sh_xform(0, AT2_BULLET);
    sh_fire(0);
}
async sub fire_at2_proxy(d: angle, n: int) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, d + ((32768/n) as angle), 0deg);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, 22fx);
    sh_xform(0, PROXY_BULLET);
    sh_fire(0);
}
sub at2(d: angle) {
    var rank: int = global(GVAR_RANK);
    var n: int = 15;
    if rank >= 1 { n = 33; }
    spawn fire_at2_normal(d, n);
    spawn fire_at2_proxy(d, n);
    spawn_lasers(d, n, 32768/n, 2, 3.6fx);
}

// Source main loop 784-831. Prep 786-790: source waits 90 then 60 after the
// timerReset (boss already spawns at the movePosTime target 0,128).
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(90);
    wait(60);                    // source t=150, first BossCard1_at
    var e: int = 3;              // $E 788
    var f: int = 10000;          // $F 789; timeout at 3300 ends the card first
    while f > 0 {
        var g: int = 3;          // $G 794
        while g > 0 {
            at();                // 797
            g = g - 1;
            wait(100);           // 798
        }
        wait(60);                // 801
        wait(60);                // 807
        var d: angle = (rand(65536) - 32768) as angle;  // %D 810
        var h: int = e;          // $H 811
        while h > 0 {
            at2(d);              // 814
            d = d + 40505bam;    // 815: +3.883222 rad = 222.5 deg
            h = h - 1;
            wait(10);            // 816
        }
        if e < 4 { e = e + 1; }  // 819-820
        wait(60);                // 822
        wait(70);                // 824
        f = f - 1;               // 826
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(25fx);            // 50x50 -> r25
    set_hurtbox(28fx);           // 56x56 -> r28
    spell_begin(0, 78, pattern, TIME_LIMIT, 500000, 0, 0);  // 771-773
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 4000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
